def is_gedf_schedulable_theorem_1(task_set, num_processors, sigma):
    # sigma must satisfy max_density_task_set <= sigma <= 1.
    # The actual implementation involves checking critical 't' values, not all 't'.
    # This is a conceptual sketch.
    for t in get_critical_t_values(task_set, num_processors, sigma):
        total_work_demand = 0
        for task_i in task_set:
            total_work_demand += calculate_work_function(task_i, t, sigma)

        available_capacity = (num_processors - (num_processors - 1) * sigma) * t

        if total_work_demand > available_capacity:
            return False # Not schedulable for this t

    return True # Schedulable if condition holds for all t
